import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.1lR7qgqY.js";const p=JSON.parse('{"title":"M3 模型入庫與存放","description":"","frontmatter":{},"headers":[],"relativePath":"build/m3-model-intake.md","filePath":"build/m3-model-intake.md","lastUpdated":null}'),o={name:"build/m3-model-intake.md"};function r(n,l,s,d,c,m){return e(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="m3-模型入庫與存放" tabindex="-1">M3 模型入庫與存放 <a class="header-anchor" href="#m3-模型入庫與存放" aria-label="Permalink to &quot;M3 模型入庫與存放&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境, 模型多於一兩個或多人共用時</li><li>狀態: 撰寫中 (僅有大綱)</li><li>資料基準日: 2026-10-26</li><li>待查證: ModelScan 的維護狀態與 TrueNAS 等 NAS 軟體的版本未查證</li></ul></div><p><strong>結論</strong>: 模型檔是推論伺服器會載入並執行的供應鏈輸入. 下載後先檢查, 記錄雜湊值, 再放進唯讀的模型存放區; 推論伺服器只從存放區讀取, 不直接從網路下載.</p><p><strong>這一塊在圖上的位置</strong>: 雲端的 Hugging Face 等模型來源, 入庫檢查主機 (ModelScan 等), 以及 NAS 上的 NFS 共享. <strong>前置模組</strong>: M0. <strong>完成後的狀態</strong>: 每個上線的模型都有來源, 版本與雜湊紀錄, 推論伺服器無法改動模型檔.</p><h2 id="m3-1-模型檔的風險" tabindex="-1">M3.1 模型檔的風險 <a class="header-anchor" href="#m3-1-模型檔的風險" aria-label="Permalink to &quot;M3.1 模型檔的風險&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>優先使用 safetensors 與 GGUF; 避免 pickle 格式 (.bin, .pt)</li><li>GGUF 的對話範本本身是 Jinja2 程式, 已有漏洞從這裡觸發</li><li>需要 trust_remote_code 的模型會執行作者提供的程式碼</li></ul><h2 id="m3-2-入庫流程" tabindex="-1">M3.2 入庫流程 <a class="header-anchor" href="#m3-2-入庫流程" aria-label="Permalink to &quot;M3.2 入庫流程&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>來源白名單: 只下載官方組織帳號發布的模型</li><li>以固定 revision 下載, 驗證校驗碼 (見 M1.5 節)</li><li>以 ModelScan 等工具掃描格式風險, 記錄雜湊值與授權 (見 K4)</li></ul><h2 id="m3-3-模型存放區" tabindex="-1">M3.3 模型存放區 <a class="header-anchor" href="#m3-3-模型存放區" aria-label="Permalink to &quot;M3.3 模型存放區&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>NAS 以 NFS 唯讀方式提供給推論伺服器</li><li>只有入庫流程能寫入</li><li>納入每週備份</li></ul><h2 id="m3-4-驗收測試" tabindex="-1">M3.4 驗收測試 <a class="header-anchor" href="#m3-4-驗收測試" aria-label="Permalink to &quot;M3.4 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>推論伺服器無法寫入模型存放區</li><li>任一上線模型都查得到來源, 版本, 雜湊與授權紀錄</li></ul>',16)])])}const h=a(o,[["render",r]]);export{p as __pageData,h as default};
